CREATE OR REPLACE FUNCTION public.operator_garage_overview(_garage_id uuid)
 RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$ WITH own AS(SELECT id FROM garages WHERE id=_garage_id AND operator_id=auth.uid()),s AS(SELECT h.* FROM garage_request_stats_hourly h JOIN own ON own.id=h.garage_id),m AS(SELECT h.model,sum(h.requests) requests FROM garage_model_stats_hourly h JOIN own ON own.id=h.garage_id WHERE h.hour>=date_trunc('week',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' GROUP BY h.model) SELECT CASE WHEN EXISTS(SELECT 1 FROM own) THEN jsonb_build_object('today',coalesce((SELECT sum(spend_usd) FROM s WHERE hour>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0),'week',coalesce((SELECT sum(spend_usd) FROM s WHERE hour>=date_trunc('week',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0),'total',coalesce((SELECT sum(spend_usd) FROM s),0),'last_request_at',(SELECT max(last_request_at) FROM s WHERE requests>0),'last_request_hour',(SELECT max(hour) FROM s WHERE requests>0),'response_ms',(SELECT percentile_cont(0.5) WITHIN GROUP(ORDER BY ttft_ms_p50) FROM s WHERE hour>=now()-interval '7 days' AND ttft_ms_p50>0),'daily',(SELECT jsonb_agg(jsonb_build_object('day',d.day::date,'requests',coalesce((SELECT sum(requests) FROM s WHERE hour>=d.day AND hour<d.day+interval '1 day'),0),'earned',coalesce((SELECT sum(spend_usd) FROM s WHERE hour>=d.day AND hour<d.day+interval '1 day'),0)) ORDER BY d.day) FROM generate_series(date_trunc('day',now() AT TIME ZONE 'UTC')-interval '13 days',date_trunc('day',now() AT TIME ZONE 'UTC'),interval '1 day') d(day)),'models',coalesce((SELECT jsonb_agg(jsonb_build_object('model',model,'requests',requests)) FROM m),'[]'::jsonb)) END $function$;

ALTER TABLE public.garages ADD COLUMN IF NOT EXISTS smart_changed_at timestamptz, ADD COLUMN IF NOT EXISTS smart_changed_by uuid;
CREATE OR REPLACE FUNCTION public.garages_audit_smart() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
BEGIN IF NEW.smart IS DISTINCT FROM OLD.smart THEN NEW.smart_changed_at:=now(); NEW.smart_changed_by:=auth.uid(); END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS garages_audit_smart ON public.garages;
CREATE TRIGGER garages_audit_smart BEFORE UPDATE OF smart ON public.garages FOR EACH ROW EXECUTE FUNCTION public.garages_audit_smart();